import httpx
from pathlib import Path
from cohezion.storage.surreal_client import _NS_HEADERS

JSONL = Path('autoresearch.jsonl')
def next_run():
    last = 281
    for line in JSONL.read_text().splitlines():
        try: last = max(last, json.loads(line).get('run', 0))
        except: pass
    return last + 1

def log(run, metric, metrics, status, desc, exp, **extra):
    entry = {'run': run, 'metric': metric, 'metrics': metrics, 'status': status,
             'description': desc, 'timestamp': int(time.time()*1000), 'segment': 99, 'confidence': 1.0,
             'asi': {'experiment': exp, **extra}}
    with JSONL.open('a') as f:
        f.write(json.dumps(entry) + '\n')
    print(f'  [{exp}] run={run} {status} metric={metric:.5f} — {desc[:90]}')

async def experiment_e25_full_analysis():
    'E25: Full DB-driven calibration analysis with honest record segmentation.'
    run = next_run()
    print(f'[E25] Full calibration analysis: run={run}')

    async with httpx.AsyncClient(timeout=5.0) as c:
        r = await c.post('http://127.0.0.1:8001/sql', headers=_NS_HEADERS,
            content=b'SELECT result, coherence FROM journey_point LIMIT 200;')
        rows = r.json()[0]['result']

    # Segment records
    segments = {'low_honest': [], 'high_honest': [], 'inflated': []}
    for row in rows:
        try:
            p = json.loads(row.get('result') or '')
            c = p.get('consensus', 0)
            vs = p.get('voice_scores', {})
            if not vs or not c: continue
            if c < 0.80: segments['low_honest'].append({'consensus': c, 'voice_scores': vs, **p})
            elif c <= 0.93: segments['high_honest'].append({'consensus': c, 'voice_scores': vs, **p})
            else: segments['inflated'].append({'consensus': c, 'voice_scores': vs, **p})
        except: pass

    print(f'  Segments: low_honest={len(segments[\"low_honest\"])} high_honest={len(segments[\"high_honest\"])} inflated={len(segments[\"inflated\"])}')

    for seg_name, recs in [('low_honest', segments['low_honest']), ('high_honest', segments['high_honest'])]:
        if not recs: continue
        mean_c = sum(r['consensus'] for r in recs) / len(recs)
        vm = {}
        for r in recs:
            for v, s in r.get('voice_scores', {}).items():
                vm.setdefault(v, []).append(s)
        voice_means = {v: round(sum(scores)/len(scores), 4) for v, scores in vm.items()}
        approved = sum(1 for r in recs if r.get('approved', False))
        print(f'  {seg_name} (n={len(recs)}): mean_consensus={mean_c:.4f} approved={approved}/{len(recs)} voices={voice_means}')

    # The most predictive voice: which has lowest mean in low_honest segment?
    if segments['low_honest']:
        vm_low = {}
        for r in segments['low_honest']:
            for v, s in r.get('voice_scores', {}).items():
                vm_low.setdefault(v, []).append(s)
        voice_lows = {v: sum(scores)/len(scores) for v, scores in vm_low.items()}
        lowest_voice = min(voice_lows, key=voice_lows.get)
        print(f'  Bottleneck voice (lowest in low_honest): {lowest_voice}={voice_lows[lowest_voice]:.4f}')

    # Key finding: what separates low_honest from high_honest?
    if segments['low_honest'] and segments['high_honest']:
        low_vm = {}
        high_vm = {}
        for r in segments['low_honest']:
            for v, s in r.get('voice_scores', {}).items(): low_vm.setdefault(v,[]).append(s)
        for r in segments['high_honest']:
            for v, s in r.get('voice_scores', {}).items(): high_vm.setdefault(v,[]).append(s)

        print(f'  Voice deltas (high - low honest):')
        for v in ['architect', 'engineer', 'ethicist', 'resource']:
            lm = sum(low_vm.get(v,[0]))/len(low_vm.get(v,[0]))
            hm = sum(high_vm.get(v,[0]))/len(high_vm.get(v,[0]))
            print(f'    {v}: low={lm:.4f} high={hm:.4f} delta={hm-lm:+.4f}')

    main_metric = len(segments['high_honest']) / max(1, len(segments['low_honest']) + len(segments['high_honest']))
    log(run, main_metric,
        {'n_low': len(segments['low_honest']), 'n_high': len(segments['high_honest']), 'n_inflated': len(segments['inflated'])},
        'keep',
        f'E25: DB segmentation. low={len(segments[\"low_honest\"])} high={len(segments[\"high_honest\"])} inflated={len(segments[\"inflated\"])}. high_pct={main_metric:.1%}',
        exp='E25', high_honest_pct=round(main_metric,4))

asyncio.run(experiment_e25_full_analysis())
