import urllib.request, base64, json, statistics as _s

def surql(query):
    headers = {
        'Authorization': 'Basic ' + base64.b64encode(b'root:root').decode(),
        'Content-Type': 'application/json',
        'surreal-ns': 'cohezion', 'surreal-db': 'main', 'Accept': 'application/json',
    }
    req = urllib.request.Request('http://127.0.0.1:8001/sql',
        data=query.encode(), headers=headers, method='POST')
    resp = urllib.request.urlopen(req, timeout=15)
    return json.loads(resp.read())

# Get samples of result field, parse JSON, collect voice scores
r = surql('SELECT result FROM journey_point WHERE result != NONE LIMIT 500;')
rows = r[0].get('result', [])

voice_stats = {'architect': [], 'engineer': [], 'ethicist': [], 'resource': []}
consensus_list = []
approved_voice = {'architect': [], 'engineer': [], 'ethicist': [], 'resource': []}
rejected_voice = {'architect': [], 'engineer': [], 'ethicist': [], 'resource': []}

for row in rows:
    try:
        data = json.loads(row['result'])
        vs = data.get('voice_scores', {})
        con = data.get('consensus', 0)
        approved = data.get('approved', False)
        consensus_list.append(con)
