                return None
            if all(
                (r := op(deepcopy(ex["input"]))) is not None and grids_equal(r, ex["output"])
                for ex in train
            ):
                return [(name, op)]
        return None

    for name, op in ops:
        transformed = []
        valid = True
        for ex in train:
            t = op(deepcopy(ex["input"]))
            if t is None:
                valid = False
                break
            transformed.append({"input": t, "output": ex["output"]})
        if not valid:
            continue
        sub = self._dfs(transformed, depth - 1, ops)
        if sub is not None:
            return [(name, op), *sub]
    return None

